#!/usr/bin/env python3
"""Generate the small MCU wire vocabulary from the canonical JSON schema."""

import json
import struct
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
schema = json.loads((ROOT / "proto/schema/controller-v1.json").read_text())
lines = [
    "// Generated by proto/tools/generate_controller.py; do not edit.",
    "#pragma once",
    "#include <cstddef>",
    "#include <cstdint>",
    "namespace sherman {",
    f"constexpr uint8_t kVersion = {schema['version']};",
    f"constexpr size_t kMaxPayload = {schema['max_payload']};",
    f"constexpr uint32_t kProfile = {schema['profile']}U;",
    "enum Message : uint8_t {",
]
for name, msg in schema["messages"].items():
    lines.append(f"  {name} = {msg['id']},")
lines += ["};", "enum Fault : uint32_t {"]
for name, value in schema["faults"].items():
    lines.append(f"  {name} = {value}U,")
lines += ["};", "constexpr int payload_size(uint8_t type) {", "  switch (type) {"]
for name, msg in schema["messages"].items():
    lines.append(f"    case {name}: return {struct.calcsize('<' + msg['format'])};")
lines += ["    default: return -1;", "  }", "}", "} // namespace sherman", ""]
(ROOT / "firmware/controller/include/sherman/wire_generated.hpp").write_text(
    "\n".join(lines)
)
